'use client';

import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Play, Pause, Zap } from 'lucide-react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

// --- Types & Interfaces ---
interface Node3D {
    id: number;
    col: number;
    row: number;
    x: number;
    y: number;
    z: number;
    vx: number;
    vy: number;
    vz: number;
    excitation: number;
}

interface BurstWave {
    radius: number;
    maxRadius: number;
    strength: number;
}

export type TopologyMode = 'MOBIUS' | 'WAVE' | 'HELIX' | 'CYLINDER';

export interface MorphingMeshProps {
    headline?: string;
    className?: string;
}

export default function MorphingMesh({
    headline = "MATRIX",
    className = "",
}: MorphingMeshProps) {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const canvasRef = useRef<HTMLCanvasElement | null>(null);

    const [isDarkMode, setIsDarkMode] = useState(true);
    const [isRunning, setIsRunning] = useState(true);
    const [topology, setTopology] = useState<TopologyMode>('MOBIUS');

    // Mesh settings
    const COLS = 40; 
    const ROWS = 16;
    const NUM_NODES = COLS * ROWS;

    // Pointer coordinates and physics state
    const pointerRef = useRef({
        x: -2000,
        y: -2000,
        targetX: -2000,
        targetY: -2000,
        radius: 180,
        isDown: false,
    });

    const nodesRef = useRef<Node3D[]>([]);
    const burstsRef = useRef<BurstWave[]>([]);
    const dimensionsRef = useRef({ width: 0, height: 0 });

    // --- Core Initialization ---
    const initMesh = useCallback(() => {
        const nodes: Node3D[] = [];
        let id = 0;

        for (let row = 0; row < ROWS; row++) {
            for (let col = 0; col < COLS; col++) {
                nodes.push({
                    id: id++,
                    col,
                    row,
                    x: (Math.random() - 0.5) * 400,
                    y: (Math.random() - 0.5) * 400,
                    z: (Math.random() - 0.5) * 400,
                    vx: 0,
                    vy: 0,
                    vz: 0,
                    excitation: 0,
                });
            }
        }
        nodesRef.current = nodes;
    }, []);

    useEffect(() => {
        initMesh();
    }, [initMesh]);

    // --- Sync Theme Safely ---
    useEffect(() => {
        const checkDark = () => {
            if (typeof window === 'undefined') return true;
            return (
                document.documentElement.classList.contains('dark') ||
                document.body?.classList.contains('dark') ||
                window.matchMedia?.('(prefers-color-scheme: dark)')?.matches || 
                false
            );
        };

        setIsDarkMode(checkDark());

        const observer = new MutationObserver(() => {
            setIsDarkMode(checkDark());
        });

        observer.observe(document.documentElement, { attributes: true, attributeFilter: ['class'] });
        if (document.body) {
            observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
        }

        const mediaQuery = typeof window !== 'undefined' ? window.matchMedia?.('(prefers-color-scheme: dark)') : null;
        const handler = () => setIsDarkMode(checkDark());

        mediaQuery?.addEventListener?.('change', handler);

        return () => {
            observer.disconnect();
            mediaQuery?.removeEventListener?.('change', handler);
        };
    }, []);

    // --- Canvas Resize Observer ---
    useEffect(() => {
        const container = containerRef.current;
        const canvas = canvasRef.current;
        if (!container || !canvas) return;

        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        const resizeObserver = new ResizeObserver((entries) => {
            for (const entry of entries) {
                const rect = entry.contentRect;
                if (rect.width === 0 || rect.height === 0) continue;

                const dpr = Math.min(window.devicePixelRatio || 1, 2);

                dimensionsRef.current = { width: rect.width, height: rect.height };
                canvas.width = Math.floor(rect.width * dpr);
                canvas.height = Math.floor(rect.height * dpr);
                canvas.style.width = `${rect.width}px`;
                canvas.style.height = `${rect.height}px`;

                ctx.setTransform(1, 0, 0, 1, 0, 0);
                ctx.scale(dpr, dpr);

                if (nodesRef.current.length === 0) {
                    initMesh();
                }
            }
        });

        resizeObserver.observe(container);
        return () => resizeObserver.disconnect();
    }, [initMesh]);

    // --- Main Render & Physics Loop ---
    useEffect(() => {
        const canvas = canvasRef.current;
        if (!canvas) return;
        const ctx = canvas.getContext('2d', { alpha: false });
        if (!ctx) return;

        let animId = 0;
        let lastTime = 0;
        let time = 0;

        const render = (currentTime: number) => {
            // Safely initialize lastTime to prevent huge delta jumps on first frame
            if (lastTime === 0) lastTime = currentTime;

            // Clamp deltaTime to max 0.1s to prevent physics explosions if tab is backgrounded
            const deltaTime = Math.min((currentTime - lastTime) / 1000, 0.1); 
            lastTime = currentTime;

            if (!isRunning) {
                animId = requestAnimationFrame(render);
                return;
            }

            time += deltaTime * 0.4;
            const { width, height } = dimensionsRef.current;
            if (width === 0 || height === 0) {
                animId = requestAnimationFrame(render);
                return;
            }

            const pointer = pointerRef.current;
            const nodes = nodesRef.current;

            if (!nodes || nodes.length < NUM_NODES) {
                animId = requestAnimationFrame(render);
                return;
            }

            const bursts = burstsRef.current;

            pointer.x += (pointer.targetX - pointer.x) * 0.08;
            pointer.y += (pointer.targetY - pointer.y) * 0.08;

            const isDark = isDarkMode;
            const bgColor = isDark ? '#09090b' : '#ffffff';
            const baseRgb = isDark ? '255, 255, 255' : '15, 23, 42';
            const activeRgb = isDark ? '255, 255, 255' : '0, 0, 0';

            ctx.fillStyle = bgColor;
            ctx.fillRect(0, 0, width, height);

            const centerX = width / 2;
            const centerY = height / 2;

            // Update color bursts
            for (let i = bursts.length - 1; i >= 0; i--) {
                const burst = bursts[i];
                burst.radius += 15;
                burst.strength *= 0.96;

                if (burst.radius > burst.maxRadius || burst.strength < 0.01) {
                    bursts.splice(i, 1);
                }
            }

            const cosT = Math.cos(time);
            const sinT = Math.sin(time);
            const cosT2 = Math.cos(time * 0.7);
            const sinT2 = Math.sin(time * 0.7);

            // 1. Math & Physics Pass
            for (let i = 0; i < NUM_NODES; i++) {
                const node = nodes[i];
                if (!node) continue;

                const u = (node.col / COLS) * Math.PI * 2;
                const vNorm = (node.row / (ROWS - 1)) * 2 - 1;

                let targetX = 0, targetY = 0, targetZ = 0;
                const R = Math.min(width, height) * 0.28;

                if (topology === 'MOBIUS') {
                    const w = vNorm * R * 0.4;
                    targetX = (R + w * Math.cos(u / 2)) * Math.cos(u);
                    targetZ = (R + w * Math.cos(u / 2)) * Math.sin(u);
                    targetY = w * Math.sin(u / 2);
                } 
                else if (topology === 'WAVE') {
                    const spacing = Math.min(width, height) * 0.035;
                    targetX = (node.col - (COLS - 1) / 2) * spacing;
                    targetZ = (node.row - (ROWS - 1) / 2) * spacing;
                    targetY = Math.sin(node.col * 0.3 + time * 3) * 35 + 
                              Math.cos(node.row * 0.3 + time * 2) * 35;
                } 
                else if (topology === 'HELIX') {
                    const helixRadius = R * 0.6;
                    const twists = 2; 
                    targetX = helixRadius * Math.cos(u * 2 + vNorm * Math.PI * twists);
                    targetZ = helixRadius * Math.sin(u * 2 + vNorm * Math.PI * twists);
                    targetY = vNorm * R * 1.5;
                } 
                else if (topology === 'CYLINDER') {
                    targetX = R * 0.7 * Math.cos(u);
                    targetZ = R * 0.7 * Math.sin(u);
                    targetY = vNorm * R;
                }

                let rx = targetX * cosT - targetZ * sinT;
                let rz = targetX * sinT + targetZ * cosT;
                let ry = targetY * cosT2 - rz * sinT2;
                rz = targetY * sinT2 + rz * cosT2;

                const spring = 0.04;
                const friction = 0.85;

                node.vx += (rx - node.x) * spring;
                node.vy += (ry - node.y) * spring;
                node.vz += (rz - node.z) * spring;

                const fov = 800;
                const cameraDist = 600;
                const scale = fov / (cameraDist + node.z);
                const projX = centerX + node.x * scale;
                const projY = centerY + node.y * scale;

                const dx = projX - pointer.x;
                const dy = projY - pointer.y;
                const dist = Math.sqrt(dx * dx + dy * dy);

                if (dist < pointer.radius && dist > 0) {
                    const ratio = 1 - dist / pointer.radius;
                    const smoothRatio = ratio * ratio * (3 - 2 * ratio);
                    node.excitation = Math.max(node.excitation, smoothRatio);
                }

                const dxCenter = projX - centerX;
                const dyCenter = projY - centerY;
                const distFromCenter = Math.sqrt(dxCenter * dxCenter + dyCenter * dyCenter);

                for (let b = 0; b < bursts.length; b++) {
                    const burst = bursts[b];
                    const ringThickness = 60;
                    const distToRing = Math.abs(distFromCenter - burst.radius);

                    if (distToRing < ringThickness) {
                        const ratio = 1 - (distToRing / ringThickness);
                        const smoothRatio = ratio * ratio * (3 - 2 * ratio);
                        node.excitation = Math.max(node.excitation, smoothRatio * burst.strength);
                    }
                }

                node.vx *= friction;
                node.vy *= friction;
                node.vz *= friction;
                node.x += node.vx;
                node.y += node.vy;
                node.z += node.vz;

                node.excitation *= 0.92;
            }

            // 2. Render Pass
            ctx.lineWidth = 1;

            for (let row = 0; row < ROWS; row++) {
                for (let col = 0; col < COLS; col++) {
                    const idx = row * COLS + col;
                    const node = nodes[idx];
                    if (!node) continue;

                    const fov = 800;
                    const cameraDist = 600;
                    const scale = fov / (cameraDist + node.z);
                    const projX = centerX + node.x * scale;
                    const projY = centerY + node.y * scale;

                    const depthAlpha = Math.max(0, Math.min(1, 1 - (node.z + 300) / 600));

                    if (node.excitation > 0.05) {
                        ctx.strokeStyle = `rgba(${activeRgb}, ${Math.min(1, depthAlpha + node.excitation)})`;
                        ctx.lineWidth = 1 + node.excitation * 1.5;
                    } else {
                        ctx.strokeStyle = `rgba(${baseRgb}, ${depthAlpha * (isDark ? 0.25 : 0.15)})`;
                        ctx.lineWidth = 1;
                    }

                    let hasRightNeighbor = false;
                    let nextColIdx = -1;

                    if (col < COLS - 1) {
                        hasRightNeighbor = true;
                        nextColIdx = row * COLS + col + 1;
                    } else if (col === COLS - 1) {
                        if (topology === 'CYLINDER') {
                            hasRightNeighbor = true;
                            nextColIdx = row * COLS + 0;
                        } else if (topology === 'MOBIUS') {
                            hasRightNeighbor = true;
                            const invertedRow = ROWS - 1 - row;
                            nextColIdx = invertedRow * COLS + 0;
                        }
                    }

                    if (hasRightNeighbor) {
                        const rightNeighbor = nodes[nextColIdx];
                        if (rightNeighbor) {
                            const rScale = fov / (cameraDist + rightNeighbor.z);
                            ctx.beginPath();
                            ctx.moveTo(projX, projY);
                            ctx.lineTo(centerX + rightNeighbor.x * rScale, centerY + rightNeighbor.y * rScale);
                            ctx.stroke();
                        }
                    }

                    if (row < ROWS - 1) {
                        const bottomIdx = (row + 1) * COLS + col;
                        const bottomNeighbor = nodes[bottomIdx];
                        if (bottomNeighbor) {
                            const bScale = fov / (cameraDist + bottomNeighbor.z);
                            ctx.beginPath();
                            ctx.moveTo(projX, projY);
                            ctx.lineTo(centerX + bottomNeighbor.x * bScale, centerY + bottomNeighbor.y * bScale);
                            ctx.stroke();
                        }
                    }

                    if (node.excitation > 0.1) {
                        ctx.fillStyle = `rgba(${activeRgb}, ${node.excitation})`;
                        ctx.beginPath();
                        ctx.arc(projX, projY, (1 + node.excitation * 2.5) * scale, 0, Math.PI * 2);
                        ctx.fill();
                    }
                }
            }

            animId = requestAnimationFrame(render);
        };

        animId = requestAnimationFrame(render);
        return () => cancelAnimationFrame(animId);
    }, [isRunning, topology, isDarkMode, COLS, ROWS, NUM_NODES]);

    const handlePointerMove = (e: React.MouseEvent<HTMLDivElement>) => {
        const container = containerRef.current;
        if (!container) return;
        const rect = container.getBoundingClientRect();
        pointerRef.current.targetX = e.clientX - rect.left;
        pointerRef.current.targetY = e.clientY - rect.top;
    };

    const handlePointerLeave = () => {
        pointerRef.current.targetX = -2000;
        pointerRef.current.targetY = -2000;
        pointerRef.current.isDown = false;
    };

    const triggerBurst = () => {
        const { width, height } = dimensionsRef.current;
        const maxR = Math.max(width, height) * 1.2;

        burstsRef.current.push({
            radius: 0,
            maxRadius: maxR,
            strength: 1.0,
        });
    };

    return (
        <div
            ref={containerRef}
            onMouseMove={handlePointerMove}
            onMouseLeave={handlePointerLeave}
            onMouseDown={() => { pointerRef.current.isDown = true; }}
            onMouseUp={() => { pointerRef.current.isDown = false; }}
            className={cn(
                // Added `touch-none` to disable scrolling while interacting with the canvas
                "group relative flex min-h-[600px] w-full touch-none select-none flex-col justify-between overflow-hidden bg-white transition-colors duration-700 dark:bg-[#09090b]",
                className
            )}
        >
            <canvas
                ref={canvasRef}
                className="absolute inset-0 block h-full w-full cursor-crosshair z-0"
            />

            <div className="absolute inset-0 z-20 flex h-full w-full flex-col justify-between p-6 md:p-10 pointer-events-none">
                <header className="flex w-full flex-wrap items-center justify-between gap-4 font-mono text-[11px] text-neutral-600 dark:text-neutral-400 pointer-events-auto">
                    <div className="flex items-center gap-2">
                        <div className="flex items-center gap-1 rounded-xl border border-neutral-200 bg-white/70 p-1 backdrop-blur-md dark:border-neutral-800 dark:bg-neutral-900/70 shadow-sm">
                            {(['MOBIUS', 'WAVE', 'HELIX', 'CYLINDER'] as TopologyMode[]).map((mode) => (
                                <button
                                    key={mode}
                                    onClick={() => setTopology(mode)}
                                    className={cn(
                                        "rounded-lg px-3 py-1.5 text-[10px] font-semibold tracking-widest transition-all duration-300",
                                        topology === mode
                                            ? "bg-neutral-900 text-white shadow-md dark:bg-white dark:text-black"
                                            : "text-neutral-500 hover:text-neutral-900 dark:text-neutral-400 dark:hover:text-white"
                                    )}
                                >
                                    {mode}
                                </button>
                            ))}
                        </div>

                        <div className="flex items-center gap-1">
                            <button
                                onClick={triggerBurst}
                                className="flex items-center gap-1.5 rounded-xl border border-neutral-200 bg-white/70 px-3 py-1.5 backdrop-blur-md transition-all hover:bg-neutral-50 dark:border-neutral-800 dark:bg-neutral-900/70 dark:hover:bg-neutral-800 shadow-sm"
                                title="Color Burst"
                            >
                                <Zap className="size-3.5" />
                                <span className="hidden sm:inline font-mono text-[10px] font-bold">BURST</span>
                            </button>

                            <button
                                onClick={() => setIsRunning((prev) => !prev)}
                                className="flex items-center gap-1.5 rounded-xl border border-neutral-200 bg-white/70 px-3 py-1.5 backdrop-blur-md transition-all hover:bg-neutral-50 dark:border-neutral-800 dark:bg-neutral-900/70 dark:hover:bg-neutral-800 shadow-sm"
                            >
                                {isRunning ? <Pause className="size-3.5" /> : <Play className="size-3.5" />}
                            </button>
                        </div>
                    </div>
                </header>
            </div>

            <main className="absolute inset-0 pointer-events-none flex flex-col items-center justify-center text-center opacity-90 z-10">
                <h1 className="font-mono text-6xl font-black tracking-tighter uppercase sm:text-8xl md:text-[10rem] text-neutral-900 dark:text-white drop-shadow-sm">
                    {headline}
                </h1>
            </main>
        </div>
    );
}

